// Package golemtest is a static policy inspection and proof kit for
// applications generated by Golem.
//
// It answers questions about the policy an application has already authored,
// for one concrete actor, without opening a database, starting an application,
// running a hook, or executing SQL. Every answer is produced by the same policy
// kernel the Golem runtime uses, so a passing assertion here is evidence about
// production behaviour rather than about a second implementation.
//
// The entry point is [New], which validates one generation of generated
// bindings, descriptors, and schema bundle together. [Kit.ForActor] builds a
// fresh, actor-scoped policy set for a single call, [Model] narrows it to one
// typed model, and [ModelPolicy.RowConstraint] resolves the rows on which an
// action is granted. [Equivalent] and [Implies] prove statements about that
// constraint through the production implication kernel.
//
// The package is not a second authorization engine. It cannot mutate or bypass
// policy, cannot manufacture a model, field, or relation identity, and cannot
// decide whether an arbitrary synthetic row is visible. Relation-aware
// execution remains an integration test through the generated Caller surface.
package golemtest

import (
	"github.com/eleven-am/golem/go/golem"
	"github.com/eleven-am/golem/go/internal/policy/bind"
	"github.com/eleven-am/golem/go/internal/policy/imply"
	"github.com/eleven-am/golem/go/internal/policy/ir"
	"github.com/eleven-am/golem/go/internal/policy/normalize"
	"github.com/eleven-am/golem/go/internal/policy/resolve"
	"github.com/eleven-am/golem/go/internal/policy/schema"
)

// Kit is an immutable, actor-independent handle on one generation of a
// generated application. It holds the validated schema registry and the
// generated policy bindings, and it holds no actor, no connection, and no
// cross-call policy cache. A Kit is safe for concurrent use.
type Kit[A any] struct {
	generation golem.SchemaDigest
	bindings   golem.ApplicationBindings[A]
	order      []golem.ModelID
	models     map[golem.ModelID]golem.ModelMetadata
	registry   *schema.Registry
	providers  ir.ProviderSet
}

// PolicySet is the immutable policy of one actor, frozen at the moment
// [Kit.ForActor] was called. It contains no actor instance and no credential,
// session, or tenant material; only the predicate operands the application's
// own policy declarations placed into their rules survive.
type PolicySet struct {
	generation golem.SchemaDigest
	models     map[golem.ModelID]golem.ModelMetadata
	policies   map[golem.ModelID]golem.FrozenPolicy
	bound      map[golem.ModelID]ir.Policy
	registry   *schema.Registry
	providers  ir.ProviderSet
}

// ModelPolicy is one actor's policy for one typed model. It retains the exact
// model descriptor it was resolved against, so every predicate a caller later
// supplies is judged against that descriptor rather than against a descriptor
// the caller names separately.
type ModelPolicy[M any] struct {
	generation golem.SchemaDigest
	model      golem.ModelID
	metadata   golem.ModelMetadata
	descriptor golem.ModelDescriptor[M]
	policy     golem.FrozenPolicy
	bound      ir.Policy
	registry   *schema.Registry
	providers  ir.ProviderSet
}

// Constraint is the resolved set of rows on which one action is granted to one
// actor for one model. It is the production resolver's own answer, in the
// production normal form, and it is immutable.
type Constraint[M any] struct {
	model      golem.ModelID
	descriptor golem.ModelDescriptor[M]
	registry   *schema.Registry
	providers  ir.ProviderSet
	condition  ir.Condition
	resolved   bool
}

// New validates one generation of generated artifacts and returns a kit bound
// to it. All three arguments must come from the same generated application:
// bindings, descriptors, and bundle must each carry the same non-zero
// generation digest, and every model, field, and relation the descriptors
// declare must be present in the schema registry the bundle builds.
//
// The bundle is the generated application's GolemGeneratedSchemaBundle. It is
// required because the descriptors alone carry no field types, providers,
// physical names, enums, or capability facts, and the production policy binder
// needs all of them.
//
// New opens no database, starts no goroutine, invokes no application hook, and
// runs no policy factory. Policy factories run only in [Kit.ForActor].
func New[A any](bindings golem.ApplicationBindings[A], descriptors golem.ApplicationDescriptors, bundle golem.SchemaBundle) (*Kit[A], error) {
	generation := bindings.GenerationDigest()
	if generation == (golem.SchemaDigest{}) {
		return nil, fail(ErrorGenerationMismatch, "application bindings carry no generation digest")
	}
	if descriptors.GenerationDigest() == (golem.SchemaDigest{}) {
		return nil, fail(ErrorGenerationMismatch, "application descriptors carry no generation digest")
	}
	if descriptors.GenerationDigest() != generation {
		return nil, fail(ErrorGenerationMismatch, "application bindings and descriptors come from different generations")
	}
	if bundle.GenerationDigest() == (golem.SchemaDigest{}) {
		return nil, fail(ErrorGenerationMismatch, "the schema bundle carries no generation digest")
	}
	if bundle.GenerationDigest() != generation {
		return nil, fail(ErrorGenerationMismatch, "the schema bundle comes from a different generation than the bindings")
	}

	declared := descriptors.Models()
	if len(declared) == 0 {
		return nil, fail(ErrorInvalidInput, "application descriptors declare no models")
	}

	models := make(map[golem.ModelID]golem.ModelMetadata, len(declared))
	order := make([]golem.ModelID, 0, len(declared))
	for _, metadata := range declared {
		id := metadata.ModelID()
		if id == (golem.ModelID{}) {
			return nil, fail(ErrorInvalidInput, "a model descriptor carries a zero model identity")
		}
		if _, duplicate := models[id]; duplicate {
			return nil, failModel(ErrorInvalidInput, "a model identity is declared more than once", id)
		}
		if err := validateModelMetadata(metadata); err != nil {
			return nil, err
		}
		models[id] = metadata
		order = append(order, id)
	}

	for _, id := range order {
		for _, relation := range models[id].Relations() {
			if _, known := models[relation.TargetModelID()]; !known {
				return nil, failField(ErrorInvalidInput, "a relation targets a model that is absent from the descriptors", id, relation.FieldID())
			}
		}
	}

	inventory := bindings.PolicyInventory()
	if len(inventory) != len(models) {
		return nil, fail(ErrorInvalidInput, "every declared model requires exactly one policy binding")
	}
	bound := make(map[golem.ModelID]struct{}, len(inventory))
	for _, id := range inventory {
		if id == (golem.ModelID{}) {
			return nil, fail(ErrorInvalidInput, "a policy binding carries a zero model identity")
		}
		if _, known := models[id]; !known {
			return nil, failModel(ErrorGenerationMismatch, "a policy binding names a model that is absent from the descriptors", id)
		}
		if _, duplicate := bound[id]; duplicate {
			return nil, failModel(ErrorInvalidInput, "a model carries more than one policy binding", id)
		}
		bound[id] = struct{}{}
	}

	registry, err := schema.New(bundle)
	if err != nil {
		return nil, fail(ErrorInvalidInput, "the schema bundle is not a valid generated schema")
	}
	if registry.GenerationDigest() != generation {
		return nil, fail(ErrorGenerationMismatch, "the validated schema registry does not carry the generation of the bindings")
	}
	providers, err := registryProviders(registry)
	if err != nil {
		return nil, err
	}
	if err := requireRegisteredMetadata(registry, order, models); err != nil {
		return nil, err
	}

	return &Kit[A]{generation: generation, bindings: bindings, order: order, models: models, registry: registry, providers: providers}, nil
}

// ForActor builds a fresh policy set for one actor. It invokes every generated
// policy factory exactly once for this call, keeps no cross-call cache, and
// discards the actor once the policies are frozen and bound.
//
// A policy factory that panics is recovered at this boundary. Its payload is
// discarded and a closed [ErrorPolicyFactory] error is returned instead.
func (kit *Kit[A]) ForActor(actor A) (PolicySet, error) {
	if kit == nil || kit.generation == (golem.SchemaDigest{}) || len(kit.models) == 0 || kit.registry == nil {
		return PolicySet{}, fail(ErrorInvalidInput, "policy kit was not produced by New")
	}

	built, err := buildGeneratedPolicySet(kit.bindings, actor)
	if err != nil {
		return PolicySet{}, err
	}
	if built.GenerationDigest() != kit.generation {
		return PolicySet{}, fail(ErrorGenerationMismatch, "the built policy set does not carry the generation of this kit")
	}

	frozen := built.Policies()
	if len(frozen) != len(kit.models) {
		return PolicySet{}, fail(ErrorPolicyFactory, "the built policy set does not cover every declared model exactly once")
	}
	policies := make(map[golem.ModelID]golem.FrozenPolicy, len(frozen))
	bound := make(map[golem.ModelID]ir.Policy, len(frozen))
	for _, policy := range frozen {
		id := policy.View().ModelID()
		if _, known := kit.models[id]; !known {
			return PolicySet{}, failModel(ErrorGenerationMismatch, "a built policy names a model that is absent from the descriptors", id)
		}
		if _, duplicate := policies[id]; duplicate {
			return PolicySet{}, failModel(ErrorPolicyFactory, "more than one policy was built for a model", id)
		}
		compiled, compileErr := compilePolicy(policy, kit.registry, kit.providers)
		if compileErr != nil {
			return PolicySet{}, failModel(ErrorPolicyFactory, "a built policy does not compile against the generated schema", id)
		}
		if compiled.ModelID() != ir.ModelID(id) {
			return PolicySet{}, failModel(ErrorPolicyFactory, "a compiled policy changed its model identity", id)
		}
		policies[id] = policy
		bound[id] = compiled
	}
	for _, id := range kit.order {
		if _, present := policies[id]; !present {
			return PolicySet{}, failModel(ErrorPolicyFactory, "no policy was built for a declared model", id)
		}
	}

	return PolicySet{
		generation: kit.generation,
		models:     kit.models,
		policies:   policies,
		bound:      bound,
		registry:   kit.registry,
		providers:  kit.providers,
	}, nil
}

// Model narrows one actor's policy set to one typed model. The descriptor must
// be the generated descriptor of a model registered in the same kit; a
// descriptor from another generated application is rejected even when its Go
// model type happens to match.
func Model[M any](policies PolicySet, descriptor golem.ModelDescriptor[M]) (ModelPolicy[M], error) {
	if policies.generation == (golem.SchemaDigest{}) || policies.models == nil || policies.policies == nil || policies.bound == nil || policies.registry == nil {
		return ModelPolicy[M]{}, fail(ErrorInvalidInput, "policy set was not produced by ForActor")
	}

	metadata := descriptor.Metadata()
	id := metadata.ModelID()
	if id == (golem.ModelID{}) {
		return ModelPolicy[M]{}, fail(ErrorInvalidInput, "model descriptor carries a zero model identity")
	}
	if descriptor.GenerationDigest() == (golem.SchemaDigest{}) || descriptor.GenerationDigest() != policies.generation {
		return ModelPolicy[M]{}, failModel(ErrorGenerationMismatch, "model descriptor does not carry this policy set's generation", id)
	}

	registered, known := policies.models[id]
	if !known {
		return ModelPolicy[M]{}, failModel(ErrorGenerationMismatch, "model descriptor is not registered in the generation this policy set was built from", id)
	}
	if !sameModelMetadata(registered, metadata) {
		return ModelPolicy[M]{}, failModel(ErrorGenerationMismatch, "model descriptor metadata differs from the descriptor registered in this kit", id)
	}

	policy, present := policies.policies[id]
	if !present {
		return ModelPolicy[M]{}, failModel(ErrorPolicyFactory, "no policy was built for a declared model", id)
	}
	compiled, compiledPresent := policies.bound[id]
	if !compiledPresent {
		return ModelPolicy[M]{}, failModel(ErrorPolicyFactory, "no compiled policy was built for a declared model", id)
	}

	return ModelPolicy[M]{
		generation: policies.generation,
		model:      id,
		metadata:   registered,
		descriptor: descriptor,
		policy:     policy,
		bound:      compiled,
		registry:   policies.registry,
		providers:  policies.providers,
	}, nil
}

// RowConstraint returns the rows on which action is granted to this actor,
// exactly as the production resolver computes it for the runtime. Model-wide
// rules and field-scoped grants participate; field-scoped denials do not hide
// rows.
func (policy ModelPolicy[M]) RowConstraint(action golem.FrozenAction) (Constraint[M], error) {
	if policy.registry == nil || policy.model == (golem.ModelID{}) || policy.generation == (golem.SchemaDigest{}) {
		return Constraint[M]{}, fail(ErrorInvalidInput, "model policy was not produced by Model")
	}
	resolved, known := boundAction(action)
	if !known {
		return Constraint[M]{}, fail(ErrorInvalidInput, "the requested action is not one of the four declared actions")
	}
	condition, err := resolve.RowConstraint(policy.bound, resolved, ir.ModelID(policy.model))
	if err != nil {
		return Constraint[M]{}, failModel(ErrorPolicyAnalysis, "the policy resolver could not resolve a row constraint for this action", policy.model)
	}
	return Constraint[M]{
		model:      policy.model,
		descriptor: policy.descriptor,
		registry:   policy.registry,
		providers:  policy.providers,
		condition:  condition,
		resolved:   true,
	}, nil
}

// Constant reports whether the constraint collapsed to a constant. When
// constant is true, value is the constant: true means every row of the model is
// reachable for this action and false means the action is refused outright.
// When constant is false the constraint is row-dependent and value is
// meaningless.
func (constraint Constraint[M]) Constant() (value bool, constant bool) {
	if !constraint.resolved {
		return false, false
	}
	return constraint.condition.Constant()
}

// View returns the resolved constraint as the same closed, immutable predicate
// view that [golem.FrozenPolicy] exposes for an authored rule, so a caller can
// walk the exact expression the resolver produced instead of comparing it to a
// predicate they must guess.
//
// Enum operands are labelled from the validated schema registry this kit was
// built from, which is the same vocabulary [Equivalent] and [Implies] accept on
// the way back in.
//
// A constraint that was not produced by [ModelPolicy.RowConstraint], or one the
// public predicate boundary refuses, yields a zero view: its RootModelID is the
// zero model identity and its canonical bytes are empty. Every accessor on that
// view is safe to call.
func (constraint Constraint[M]) View() golem.FrozenPredicateView {
	if !constraint.resolved || constraint.registry == nil {
		return golem.FrozenPredicate{}.View()
	}
	frozen, err := bind.FreezeCondition(constraint.model, constraint.condition, bind.RegistryEnumLabels(constraint.registry))
	if err != nil {
		return golem.FrozenPredicate{}.View()
	}
	return frozen.View()
}

// CanonicalBytes returns the deterministic encoding of the normalized
// constraint. Two constraints with identical bytes are the same expression, but
// the converse does not hold: logically equivalent constraints may encode
// differently. Use [Equivalent] to compare meaning; use these bytes only as
// stable evidence in a diagnostic or a golden record.
func (constraint Constraint[M]) CanonicalBytes() []byte {
	if !constraint.resolved {
		return nil
	}
	canonical, err := ir.CanonicalCondition(constraint.condition)
	if err != nil {
		return nil
	}
	return canonical
}

// Equivalent reports whether constraint and expected admit the same rows. It is
// implication proved in both directions through the production implication
// kernel, after the same normalization production applies; it is deliberately
// not a comparison of [Constraint.CanonicalBytes].
//
// The expected predicate is frozen against the model descriptor the constraint
// retains, so it cannot be judged against a different model than the one whose
// policy produced the constraint.
//
// A false result means "not proved". The production kernel is conservative and
// bounded: it refuses proofs that are too large and refuses vacuous proofs
// drawn from an unsatisfiable selector. A refusal it reports as a failure is
// returned as an [ErrorPolicyAnalysis] error rather than as a false answer.
func Equivalent[M any](constraint Constraint[M], expected golem.Predicate[M]) (bool, error) {
	required, err := constraint.require(expected)
	if err != nil {
		return false, err
	}
	forward, err := prove(constraint.condition, required)
	if err != nil || !forward {
		return false, err
	}
	return prove(required, constraint.condition)
}

// Implies reports whether every row admitted by constraint also satisfies
// expected. It proves one direction through the production implication kernel,
// with that kernel's existing bounds and refusals.
//
// The expected predicate is frozen against the model descriptor the constraint
// retains. A false result means "not proved"; see [Equivalent] for what the
// kernel refuses to prove.
func Implies[M any](constraint Constraint[M], expected golem.Predicate[M]) (bool, error) {
	required, err := constraint.require(expected)
	if err != nil {
		return false, err
	}
	return prove(constraint.condition, required)
}

func (constraint Constraint[M]) require(expected golem.Predicate[M]) (ir.Condition, error) {
	if !constraint.resolved || constraint.registry == nil || constraint.model == (golem.ModelID{}) {
		return ir.Condition{}, fail(ErrorInvalidInput, "constraint was not produced by RowConstraint")
	}
	frozen, err := expected.Freeze(constraint.descriptor)
	if err != nil {
		return ir.Condition{}, failModel(ErrorInvalidInput, "the expected predicate cannot be frozen against the model descriptor this constraint retains", constraint.model)
	}
	required, err := bind.Predicate(frozen, constraint.registry, constraint.providers)
	if err != nil {
		return ir.Condition{}, failModel(ErrorPolicyAnalysis, "the expected predicate does not bind against the generated schema", constraint.model)
	}
	if required.ModelID() != ir.ModelID(constraint.model) {
		return ir.Condition{}, failModel(ErrorPolicyAnalysis, "the expected predicate resolved to a different model than this constraint", constraint.model)
	}
	return required, nil
}

func prove(selecting, required ir.Condition) (bool, error) {
	proved, err := imply.Condition(selecting, required)
	if err != nil {
		return false, fail(ErrorPolicyAnalysis, "the policy implication kernel refused to decide this proof")
	}
	return proved, nil
}

func boundAction(action golem.FrozenAction) (ir.Action, bool) {
	switch action {
	case golem.FrozenActionRead:
		return ir.ActionRead, true
	case golem.FrozenActionCreate:
		return ir.ActionCreate, true
	case golem.FrozenActionUpdate:
		return ir.ActionUpdate, true
	case golem.FrozenActionDelete:
		return ir.ActionDelete, true
	default:
		return 0, false
	}
}

func compilePolicy(frozen golem.FrozenPolicy, registry *schema.Registry, providers ir.ProviderSet) (ir.Policy, error) {
	bound, err := bind.Policy(frozen, registry, providers)
	if err != nil {
		return ir.Policy{}, err
	}
	return normalize.Policy(bound)
}

func registryProviders(registry *schema.Registry) (ir.ProviderSet, error) {
	declared := registry.Providers()
	values := make([]ir.Provider, 0, len(declared))
	for _, provider := range declared {
		switch provider {
		case golem.SQLite:
			values = append(values, ir.ProviderSQLite)
		case golem.PostgreSQL:
			values = append(values, ir.ProviderPostgreSQL)
		default:
			return 0, fail(ErrorInvalidInput, "the schema bundle declares a provider this kit does not recognise")
		}
	}
	providers, err := ir.NewProviderSet(values...)
	if err != nil {
		return 0, fail(ErrorInvalidInput, "the schema bundle declares no usable provider set")
	}
	return providers, nil
}

func requireRegisteredMetadata(registry *schema.Registry, order []golem.ModelID, models map[golem.ModelID]golem.ModelMetadata) error {
	for _, id := range order {
		if !registry.HasModel(id) {
			return failModel(ErrorGenerationMismatch, "a declared model is absent from the validated schema", id)
		}
		metadata := models[id]
		for _, field := range metadata.ScanFields() {
			if !registry.HasField(id, field) {
				return failField(ErrorGenerationMismatch, "a declared scan field is absent from the validated schema", id, field)
			}
		}
		for _, relation := range metadata.Relations() {
			endpoint, known := registry.RelationEndpoint(id, relation.FieldID(), relation.RelationID())
			if !known {
				return failField(ErrorGenerationMismatch, "a declared relation endpoint is absent from the validated schema", id, relation.FieldID())
			}
			if endpoint.TargetModelID() != relation.TargetModelID() {
				return failField(ErrorGenerationMismatch, "a declared relation targets a different model than the validated schema", id, relation.FieldID())
			}
		}
	}
	return nil
}

func buildGeneratedPolicySet[A any](bindings golem.ApplicationBindings[A], actor A) (set golem.GeneratedPolicySet, err error) {
	defer func() {
		if recover() != nil {
			set = golem.GeneratedPolicySet{}
			err = fail(ErrorPolicyFactory, "a generated policy factory panicked")
		}
	}()
	built, buildErr := golem.BuildGeneratedPolicySet(bindings, actor)
	if buildErr != nil {
		return golem.GeneratedPolicySet{}, fail(ErrorPolicyFactory, "a generated policy factory did not produce a complete policy set")
	}
	return built, nil
}

func validateModelMetadata(metadata golem.ModelMetadata) error {
	id := metadata.ModelID()

	scan := make(map[golem.FieldID]struct{})
	for _, field := range metadata.ScanFields() {
		if field == (golem.FieldID{}) {
			return failModel(ErrorInvalidInput, "a model declares a zero scan field identity", id)
		}
		if _, duplicate := scan[field]; duplicate {
			return failField(ErrorInvalidInput, "a model declares a scan field more than once", id, field)
		}
		scan[field] = struct{}{}
	}
	if len(scan) == 0 {
		return failModel(ErrorInvalidInput, "a model declares no scan fields", id)
	}

	write := make(map[golem.FieldID]struct{})
	for _, field := range metadata.WriteFields() {
		if field == (golem.FieldID{}) {
			return failModel(ErrorInvalidInput, "a model declares a zero write field identity", id)
		}
		if _, duplicate := write[field]; duplicate {
			return failField(ErrorInvalidInput, "a model declares a write field more than once", id, field)
		}
		if _, persisted := scan[field]; !persisted {
			return failField(ErrorInvalidInput, "a model declares a write field that is absent from its scan fields", id, field)
		}
		write[field] = struct{}{}
	}

	keys := make(map[golem.KeyID]struct{})
	primaries := 0
	for _, identity := range metadata.Identities() {
		if identity.ModelID() != id {
			return failModel(ErrorInvalidInput, "a model declares an identity that belongs to another model", id)
		}
		if identity.KeyID() == (golem.KeyID{}) {
			return failModel(ErrorInvalidInput, "a model declares a zero identity key", id)
		}
		if _, duplicate := keys[identity.KeyID()]; duplicate {
			return failModel(ErrorInvalidInput, "a model declares an identity key more than once", id)
		}
		keys[identity.KeyID()] = struct{}{}
		switch identity.Kind() {
		case golem.PrimaryIdentity:
			primaries++
		case golem.UniqueIdentity:
		default:
			return failModel(ErrorInvalidInput, "a model declares an identity of an unknown kind", id)
		}
		fields := identity.Fields()
		if len(fields) == 0 {
			return failModel(ErrorInvalidInput, "a model declares an identity with no fields", id)
		}
		members := make(map[golem.FieldID]struct{}, len(fields))
		for _, field := range fields {
			if field == (golem.FieldID{}) {
				return failModel(ErrorInvalidInput, "a model declares a zero identity field identity", id)
			}
			if _, duplicate := members[field]; duplicate {
				return failField(ErrorInvalidInput, "a model declares an identity field more than once", id, field)
			}
			if _, persisted := scan[field]; !persisted {
				return failField(ErrorInvalidInput, "a model declares an identity field that is absent from its scan fields", id, field)
			}
			members[field] = struct{}{}
		}
	}
	if primaries > 1 {
		return failModel(ErrorInvalidInput, "a model declares more than one primary identity", id)
	}

	type relationEndpoint struct {
		id   golem.RelationID
		role golem.RelationRole
	}
	relationFields := make(map[golem.FieldID]struct{})
	relationEndpoints := make(map[relationEndpoint]struct{})
	for _, relation := range metadata.Relations() {
		field := relation.FieldID()
		if relation.ModelID() != id {
			return failModel(ErrorInvalidInput, "a model declares a relation that belongs to another model", id)
		}
		if field == (golem.FieldID{}) {
			return failModel(ErrorInvalidInput, "a model declares a zero relation field identity", id)
		}
		if relation.RelationID() == (golem.RelationID{}) {
			return failField(ErrorInvalidInput, "a model declares a zero relation identity", id, field)
		}
		if relation.TargetModelID() == (golem.ModelID{}) {
			return failField(ErrorInvalidInput, "a model declares a relation with a zero target model", id, field)
		}
		if _, duplicate := relationFields[field]; duplicate {
			return failField(ErrorInvalidInput, "a model declares a relation field more than once", id, field)
		}
		if _, persisted := scan[field]; persisted {
			return failField(ErrorInvalidInput, "a model declares a relation field that collides with a scan field", id, field)
		}
		switch relation.Role() {
		case golem.RelationSource, golem.RelationInverse:
		default:
			return failField(ErrorInvalidInput, "a model declares a relation with an unknown role", id, field)
		}
		switch relation.Cardinality() {
		case golem.RelationToOne, golem.RelationToMany:
		default:
			return failField(ErrorInvalidInput, "a model declares a relation with an unknown cardinality", id, field)
		}
		endpoint := relationEndpoint{id: relation.RelationID(), role: relation.Role()}
		if _, duplicate := relationEndpoints[endpoint]; duplicate {
			return failField(ErrorInvalidInput, "a model declares the same relation endpoint more than once", id, field)
		}
		relationFields[field] = struct{}{}
		relationEndpoints[endpoint] = struct{}{}
	}

	return nil
}

func sameModelMetadata(left, right golem.ModelMetadata) bool {
	if left.ModelID() != right.ModelID() {
		return false
	}
	if !sameFieldOrder(left.ScanFields(), right.ScanFields()) {
		return false
	}
	if !sameFieldOrder(left.WriteFields(), right.WriteFields()) {
		return false
	}
	leftIdentities, rightIdentities := left.Identities(), right.Identities()
	if len(leftIdentities) != len(rightIdentities) {
		return false
	}
	for index := range leftIdentities {
		if leftIdentities[index].ModelID() != rightIdentities[index].ModelID() {
			return false
		}
		if leftIdentities[index].KeyID() != rightIdentities[index].KeyID() {
			return false
		}
		if leftIdentities[index].Kind() != rightIdentities[index].Kind() {
			return false
		}
		if !sameFieldOrder(leftIdentities[index].Fields(), rightIdentities[index].Fields()) {
			return false
		}
	}
	leftRelations, rightRelations := left.Relations(), right.Relations()
	if len(leftRelations) != len(rightRelations) {
		return false
	}
	for index := range leftRelations {
		if leftRelations[index] != rightRelations[index] {
			return false
		}
	}
	return true
}

func sameFieldOrder(left, right []golem.FieldID) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		if left[index] != right[index] {
			return false
		}
	}
	return true
}
